package odc;
import java.util.*;
import static odc.PhysicalTopology.*;
public final class LogicalLinksTest {
 static int n;static void check(boolean x,String m){n++;if(!x)throw new AssertionError(m);}
 static Pos p(int x){return new Pos(x,0,0);}static UUID id(int i){return new UUID(0,i);}
 static Device dev(int i,Type t,int x,boolean powered){return new Device(id(i),t,"n","m",p(x),0,1000,-1,powered,null,0,-1);}
 static void cell(PhysicalTopology t,int x,Kind k,Device... d){t.put(p(x),new Cell(k,Arrays.asList(d)));}
 public static void main(String[] args){LogicalLinks l=new LogicalLinks();check(LogicalLinks.speed(1)==100&&LogicalLinks.speed(2)==1000&&LogicalLinks.speed(3)==100000,"tiers");check(l.add(id(1),id(2),0)==null,"invalid");check(l.add(id(1),id(1),1)==null,"self");LogicalLinks.Link a=l.add(id(1),id(2),1);check(a!=null&&l.add(id(1),id(2),2)==null,"duplicate");check(l.add(id(3),id(2),3)!=null,"multiple uplinks");check(l.replace(id(1),id(2),2)&&l.find(id(1),id(2)).id.equals(a.id),"upgrade preserves id");check(!l.replace(id(1),id(2),1),"no downgrade");
 PhysicalTopology t=new PhysicalTopology();cell(t,0,Kind.TERMINAL,dev(1,Type.TERMINAL,0,true));cell(t,1,Kind.DATA);cell(t,2,Kind.RACK,dev(2,Type.SWITCH,2,true));cell(t,3,Kind.TERMINAL,dev(3,Type.TERMINAL,3,true));check(LogicalLinks.state(t.view(p(0),x->true),id(1),id(2))==LogicalLinks.State.ACTIVE,"active");t.put(p(1),null);check(LogicalLinks.state(t.view(p(0),x->true),id(1),id(2))==LogicalLinks.State.SEPARATED&&l.all().size()==2,"split retains links");cell(t,1,Kind.DATA);check(LogicalLinks.state(t.view(p(0),x->true),id(1),id(2))==LogicalLinks.State.ACTIVE,"restore");check(LogicalLinks.state(t.view(p(0),x->!x.equals(p(1))),id(1),id(2))==LogicalLinks.State.UNVERIFIED,"unloaded cable");cell(t,2,Kind.RACK,dev(2,Type.SWITCH,2,false));check(LogicalLinks.state(t.view(p(0),x->true),id(1),id(2))==LogicalLinks.State.OFFLINE,"unpowered");
 LogicalLinks copy=new LogicalLinks();for(LogicalLinks.Link z:l.all())check(copy.restore(z),"restore records");check(!copy.restore(a),"restore duplicate");check(copy.removeDevice(id(2)).size()==2&&copy.removeDevice(id(2)).isEmpty(),"delete refunds once");check(l.remove(id(1),id(2)).tier==2&&l.remove(id(1),id(2))==null,"disconnect once, correct tier");check(LogicalLinks.automaticId(LogicalLinks.Kind.FIBER,id(4),id(5)).equals(LogicalLinks.automaticId(LogicalLinks.Kind.FIBER,id(4),id(5))),"stable fiber ID");Random rng=new Random(613);int[] ports=new int[8],tiers=new int[8],stock={0,100,100,100};for(int k=0;k<20000;k++){int port=rng.nextInt(8),bay=rng.nextInt(9),tier=1+rng.nextInt(3),op=rng.nextInt(3);if(op==0&&stock[tier]>0&&LanPorts.canConnect(ports,8,port,bay,tier)){stock[tier]--;ports[port]=bay+1;tiers[port]=tier;}else if(op==1&&stock[tier]>0&&LanPorts.canUpgrade(ports,tiers,8,port,tier)){stock[tier]--;stock[LanPorts.tier(ports,tiers,port)]++;tiers[port]=tier;}else if(op==2){int removed=LanPorts.remove(ports,tiers,port);if(removed>0)stock[removed]++;}int[] held=stock.clone();Set<Integer> occupied=new HashSet<>();for(int j=0;j<8;j++)if(ports[j]>0){held[LanPorts.tier(ports,tiers,j)]++;check(occupied.add(ports[j]),"unique bay");}for(int j=1;j<=3;j++)check(held[j]==100,"per-tier conservation");}System.out.println("LogicalLinksTest PASS: "+n+" checks");}
}
